def solve(gin, shape_w, shape_h, sep_rows, sep_slot_cols):
    # generic: bands of shape copies separated by uniform separator rows
    h = len(gin); w = len(gin[0])
    bands = []   # list of (k, {c: s})
    k = 0; r = 0
    band_rows = []
    cur = []
    for r in range(h):
        if any(v == 3 for v in gin[r]) or all(v == 0 for v in gin[r]):
            if cur: band_rows.append(cur); cur = []
            band_rows.append(('sep', r)) if False else None
            # mark separator row group lazily
        else:
            cur.append(r)
    # simpler: detect separator = rows containing 3
    band_rows = []
    cur = []
    seps = []
    for r in range(h):
        if any(v == 3 for v in gin[r]):
            if cur: band_rows.append(list(cur)); cur = []
            seps.append(r)
        else:
            cur.append(r)
    if cur: band_rows.append(list(cur))
    slot_width = shape_w + 1
    # separator band spans len(seps) rows; number of bands = len(band_rows)+1 with separator inserted at its position
    # find separator band index: bands before it
    sep_start = seps[0]
    k_sep = sum(1 for b in band_rows if b[0] < sep_start)
    # coarse grid: for each band k, find slots; also need slots count = (w - shape_w)//slot_width + 1
    nslots = sep_slot_cols if False else (w - shape_w)//slot_width + 1
    coarse = {}   # (k,c) -> 1
    band_index = {}
    bands_at = []
    kk = 0
    for b in band_rows:
        bands_at.append((kk, b))
        kk += 1
        if b[0] == sep_start:
            bands_at.append((kk, 'SEP'))
            kk += 1
    slots_by_band = []
    for (k_, b) in bands_at:
        if b == 'SEP':
            slots_by_band.append((k_, None))
            continue
        d = {}
        for s in range(0, w - shape_w + 1, slot_width):
            if gin[b[0]][s] == 2:
                c = s // slot_width
                d[c] = s
        slots_by_band.append((k_, d))
    out = [row[:] for row in gin]
    for r in seps:
        out[r] = [0]*w
    for (k_, d) in slots_by_band:
        if d is None: continue
        base = bands_at[[x[0] for x in bands_at].index(k_)]
        rows = base[1]
        for c, s in d.items():
            for (rr, cc) in cells_shape(shape_w, shape_h, gin, rows, s):
                out[rows[0]+rr][s+cc] = 2
            # mark rel(k_, c) if it is a shape cell
            if (k_, c) in shape_set:
                out[rows[0]+k_][s+c] = 8
    # separator shapes: coarse row k_sep must equal shape row k_sep: cells at cols where shape has cell
    for cc in range(shape_w):
        if (k_sep, cc) in shape_set:
            s = cc * slot_width
            for (rr, pc) in cells_shape(shape_w, shape_h, gin, band_rows[0], 0):
                out[sep_start+rr][s+pc] = 2
            if (k_sep, cc) in shape_set:
                out[sep_start+k_sep][s+cc] = 8
    return out

def cells_shape(shape_w, shape_h, gin, rows, s):
    res = []
    for rr in range(shape_h):
        for cc in range(shape_w):
            if gin[rows[0]+rr][s+cc] == 2:
                res.append((rr, cc))
    return res

